function stableJson(value) {
  const normalize = (entry) => {
    if (Array.isArray(entry)) return entry.map(normalize);
    if (entry && typeof entry === "object") {
      return Object.keys(entry).sort().reduce((result, key) => {
        result[key] = normalize(entry[key]);
        return result;
      }, {});
    }
    return entry;
  };
  return JSON.stringify(normalize(value));
}

function sameJsonValue(left, right) {
  if (left === right) return true;
  if (left && right && typeof left === "object" && typeof right === "object") {
    const leftArray = Array.isArray(left);
    if (leftArray !== Array.isArray(right)) return false;
    if (leftArray) {
      if (left.length !== right.length) return false;
      for (let index = 0; index < left.length; index += 1) {
        const a = left[index];
        const b = right[index];
        const arrayValue = (value) => (
          ["undefined", "function", "symbol"].includes(typeof value) ? null : value
        );
        if (!sameJsonValue(arrayValue(a), arrayValue(b))) return false;
      }
      return true;
    }
    const serializableKeys = (value) => Object.keys(value).filter((key) => (
      !["undefined", "function", "symbol"].includes(typeof value[key])
    ));
    const leftKeys = serializableKeys(left);
    const rightKeys = serializableKeys(right);
    if (leftKeys.length !== rightKeys.length) return false;
    for (const key of leftKeys) {
      if (!Object.prototype.hasOwnProperty.call(right, key) || !sameJsonValue(left[key], right[key])) return false;
    }
    return true;
  }
  return stableJson(left) === stableJson(right);
}

