    if (now - Number(this.lastCalendarZoomWheelAt || 0) < 55) return true;
    this.lastCalendarZoomWheelAt = now;
    const direction = Number(event.deltaY) < 0 ? 1 : -1;
    const requested = this.calendarZoom + direction * CALENDAR_ZOOM_STEP;
