        const items=invalidRange?[]:records.filter(r=>terms.every(q=>r.text.includes(q))&&(!statusFilter.value||String(r.item.status)===statusFilter.value)&&(!projectFilter.value||(projectFilter.value==='__none'?!v.projectMembership(r.item).length:v.projectMembership(r.item).includes(projectFilter.value)))&&(!tagFilter.value||(Array.isArray(r.item.tags)?r.item.tags:[r.item.tags]).includes(tagFilter.value))&&(!dbFilter.value||r.item.databaseId===dbFilter.value)&&(!fromDate.value||r.day&&r.end>=fromDate.value)&&(!toDate.value||r.day&&r.day<=toDate.value));
        items.sort((a,b)=>sort.value==='title'?String(a.item.title||'').localeCompare(String(b.item.title||''),'ko'):!a.day?(!b.day?0:1):!b.day?-1:(sort.value==='old'?1:-1)*a.day.localeCompare(b.day)||String(a.item.title||'').localeCompare(String(b.item.title||''),'ko'));
        count.textContent=invalidRange?'날짜 범위를 확인하세요':`${items.length}개 일정`;
        for(const record of items.slice(0,limit)){
          const {item,date,db}=record,row=list.createEl(this.from?'div':'label',{cls:'sien-project-assign-row',attr:{'data-item-id':keyOf(item)}});let check;
          if(!this.from){check=row.createEl('input',{type:'checkbox',attr:{'aria-label':(item.title||'이름 없음')+' 프로젝트 포함'}});check.checked=v.projectMembership(item).includes(project.id);check.disabled=d.type==='select'&&v.projectMembership(item).length>0&&!check.checked;if(check.disabled)check.title='다른 프로젝트의 일정';}
          const info=row.createDiv({cls:'sien-project-assign-info'});info.createEl('strong',{text:item.title||'이름 없음',cls:'sien-project-assign-title'});const meta=info.createDiv({cls:'sien-project-assign-meta'});meta.createSpan({text:date.absolute+(date.time?' · '+date.time:''),cls:'sien-project-assign-date'});
          for(const text of [statusDef?pl.optionLabel(statusDef,item.status):item.status,db?.name,...v.projectMembership(item).map(id=>pl.optionLabel(d,id))].filter(Boolean))meta.createSpan({text});
          const tags=Array.isArray(item.tags)?item.tags:[item.tags];if(tags.some(Boolean)){const chips=info.createDiv({cls:'sien-project-assign-tags'});for(const id of tags.filter(Boolean)){const chip=chips.createSpan({text:pl.optionLabel(tagDef,id),cls:'sien-property-tag is-multi-select'});chip.style.setProperty('--property-color',pl.optionColor(tagDef,id));}}
          if(this.from){const choose=button(row,'연결',async()=>{choose.disabled=true;if(wouldCycle(pl.items,keyOf,keyOf(item),keyOf(this.from))){new Notice('순환 연결은 만들 수 없습니다.');choose.disabled=false;return;}const membership=v.projectMembership(item),targetId=membership.includes(project.id)?project.id:membership[0]||project.id;const value=d.type==='multi-select'?[...new Set([...membership,project.id])]:project.id;if(!membership.length&&!await v.saveProjectValue(item,d,value)){choose.disabled=false;return;}if(!await v.saveProjectValue(item,{key:BRANCHES,name:'분기 기준'},{...item[BRANCHES],[targetId]:keyOf(this.from)})){choose.disabled=false;return;}if(await v.changeProjectPredecessor(item,this.from,true))this.close();else choose.disabled=false;});}
          else check.addEventListener('change',async()=>{check.disabled=true;const value=d.type==='multi-select'?[...new Set([...v.projectMembership(item).filter(id=>id!==project.id),...(check.checked?[project.id]:[])])]:check.checked?project.id:'';if(!await v.saveProjectValue(item,d,value))check.checked=!check.checked;check.disabled=false;});
        }
